import json

# Search for any year projection through 2024
with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Flatten the JSON and search
def find_years(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(find_years(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_years(v, f"{path}[{i}]"))
    elif isinstance(obj, str):
        if any(y in obj for y in ['2014', '2015', '2016', '2017', '2018', '2019', '2020', '2021', '2022', '2023', '2024']):
            results.append((path, obj[:200]))
    return results

results = find_years(data)
for path, text in results[:20]:
    print(f"{path}: {text}")
    print("---")
