# Search more thoroughly for any budget projections in all resources
import os
import re

for root, dirs, files in os.walk('/app/resources'):
    for fname in files:
        if fname.endswith('.txt') or fname.endswith('.json'):
            fpath = os.path.join(root, fname)
            try:
                with open(fpath, 'r') as f:
                    content = f.read()
                # Look for budget projections for 2020+
                matches = re.findall(r'202[0-9].*(?:deficit|surplus|billion|trillion)', content, re.IGNORECASE)
                if matches and '2025' in str(matches):
                    print(f"Found in {fname}:")
                    for m in matches[:5]:
                        print(f"  {m}")
                    print()
            except:
                pass
